/* The common header, as it sits at the start of every record: 32 bytes, no padding. */
typedef struct ta_msg_wire_header {
    uint16_t kind; /* ta_msg_kind */
    uint16_t flags;
    uint32_t size;
    uint64_t seq;
    uint64_t session;
    uint64_t at;
} ta_msg_wire_header;
_Static_assert(sizeof(ta_msg_wire_header) == 32, "header");

/* The header fields a caller chooses; kind and size come from the message, seq from the reservation. */
typedef struct ta_msg_head {
    uint16_t flags; /* the message's flags (bits 0..7) and the common flags (bits 8..15) */
    uint64_t session;
    uint64_t at;
} ta_msg_head;

/*
 * h2c.time: Move the system clock.
 *
 * The header `at` is the new time. It never moves back. Delayed sends due by
 * then become runnable envelopes, in due order, then send order. Applied
 * between macrosteps. Admission of an earlier event does not ensure that event
 * has finished; the host awaits input_completed before posting time when it
 * requires that execution order.
 *
 * Ring h2c, kind 0x0101, 32 fixed bytes, 0 spans. Replied to by c2h.wake.
 *
 * Fields:
 */
typedef struct ta_msg_h2c_time_wire {
    ta_msg_wire_header header;
} ta_msg_h2c_time_wire;
_Static_assert(sizeof(ta_msg_h2c_time_wire) == 32, "h2c.time");

typedef struct ta_msg_h2c_time {
    ta_msg_head head;
} ta_msg_h2c_time;

/*
 * ta_msg_h2c_time_size sets *size to the exact size in bytes of the h2c.time
 * record that ta_msg_h2c_time_write stores for data: 32 fixed bytes, so always
 * that many. It never allocates. It cannot fail. data and size must not be
 * NULL.
 */
ta_result ta_msg_h2c_time_size(const ta_msg_h2c_time *data, uint32_t *size);

/*
 * ta_msg_h2c_time_write fills the reservation `to` with the h2c.time record
 * for data: the header (kind 0x0101, the flags, session and at of data->head,
 * the size, and the seq of the reservation), the fixed fields, the bytes of
 * each span, and zero for every pad and rounding byte, so that all of to->size
 * bytes are stored. It needs a reservation of exactly the size
 * ta_msg_h2c_time_size answers (ring.h: ta_ring_reserve), and the ta_bytes of
 * data must not overlap it. TA_ERR_INVALID, with nothing stored: no bytes, a
 * size other than the measured one, a flag bit that h2c.time does not define,
 * an enum or bool field outside its set (the reader would refuse the record),
 * or a ta_bytes with a length and no pointer. TA_ERR_NOMEM, with nothing
 * stored: the size does not fit a u32. The caller then commits the
 * reservation, or abandons it on an error. It never allocates, and the data
 * may be freed when it returns.
 */
ta_result ta_msg_h2c_time_write(const ta_msg_h2c_time *data, const ta_ring_reservation *to);

/*
 * ta_msg_h2c_time_get decodes the h2c.time record into *out. It needs a record
 * that ta_record_check accepted, so every span is inside it and every enum and
 * bool is in range. The scalars of *out are copies of the record's snapshot
 * (not of the ring bytes, which a host may be rewriting) and may outlive the
 * record. Each ta_bytes of *out points into the record and is valid only until
 * ta_ring_release; its bytes are untrusted, and text is not checked for UTF-8.
 * TA_ERR_INVALID: the record is of another kind, and *out is untouched. It
 * never allocates and reads nothing outside record->fixed and the validated
 * spans.
 */
ta_result ta_msg_h2c_time_get(const ta_record *record, ta_msg_h2c_time *out);

/*
 * h2c.event: An external event for a session.
 *
 * Header `session` names a resident session, or is 0 and `target` gives an
 * address. Admitted into the pool when the pool is below its watermark. An
 * event for an unloaded address waits in the pool and core asks for the
 * session with c2h.load_needed. A capacity refusal consumes and bounces the
 * record, allowing later controls to progress.
 *
 * A live input runs at system time when taken; its header at does not advance
 * that clock. A replay input moves its prepared session clock at take.
 * Complete event metadata must also fit the expanded c2h.input. Service events
 * carry invocation_seq, checked again at take. Zero means ordinary input, or
 * an application-supplied replay seed.
 *
 * Ring h2c, kind 0x0102, 104 fixed bytes, 6 spans. Replied to by c2h.input,
 * c2h.bounced, c2h.load_needed, c2h.input_refused, c2h.input_completed. See
 * also h2c.withdraw.
 *
 * Fields:
 *   target (text): the address (family/name), when session is 0
 *   name (text): the dotted event name, as bytes (reference/names.md)
 *   sendid (text): _event.sendid, or empty
 *   origin (text): _event.origin, or empty
 *   origin_type (text): _event.origintype, or empty
 *   invokeid (text): _event.invokeid for an invoked service, or empty
 *   invocation_seq (seq): c2h.invoke seq for a live service instance; 0 for
 *       ordinary input or replay seeds
 *   data (vref): _event.data
 *   type (event_type): almost always external
 */
typedef struct ta_msg_h2c_event_wire {
    ta_msg_wire_header header;
    ta_span32 target;
    ta_span32 name;
    ta_span32 sendid;
    ta_span32 origin;
    ta_span32 origin_type;
    ta_span32 invokeid;
    uint64_t invocation_seq;
    uint64_t data;
    uint8_t type; /* ta_msg_event_type */
    uint8_t pad_end[7];
} ta_msg_h2c_event_wire;
_Static_assert(sizeof(ta_msg_h2c_event_wire) == 104, "h2c.event");
_Static_assert(offsetof(ta_msg_h2c_event_wire, target) == 32, "h2c.event.target");
_Static_assert(offsetof(ta_msg_h2c_event_wire, name) == 40, "h2c.event.name");
_Static_assert(offsetof(ta_msg_h2c_event_wire, sendid) == 48, "h2c.event.sendid");
_Static_assert(offsetof(ta_msg_h2c_event_wire, origin) == 56, "h2c.event.origin");
_Static_assert(offsetof(ta_msg_h2c_event_wire, origin_type) == 64, "h2c.event.origin_type");
_Static_assert(offsetof(ta_msg_h2c_event_wire, invokeid) == 72, "h2c.event.invokeid");
_Static_assert(offsetof(ta_msg_h2c_event_wire, invocation_seq) == 80, "h2c.event.invocation_seq");
_Static_assert(offsetof(ta_msg_h2c_event_wire, data) == 88, "h2c.event.data");
_Static_assert(offsetof(ta_msg_h2c_event_wire, type) == 96, "h2c.event.type");

typedef struct ta_msg_h2c_event {
    ta_msg_head head;
    ta_bytes target;
    ta_bytes name;
    ta_bytes sendid;
    ta_bytes origin;
    ta_bytes origin_type;
    ta_bytes invokeid;
    uint64_t invocation_seq;
    uint64_t data;
    uint8_t type; /* ta_msg_event_type */
} ta_msg_h2c_event;

