    ta_msg_wire_header header;
    uint64_t macrostep;
    uint64_t source_seq;
    uint64_t from_session;
    ta_span32 name;
    ta_span32 sendid;
    ta_span32 origin;
    ta_span32 origin_type;
    ta_span32 invokeid;
    uint64_t data;
    uint8_t source; /* ta_msg_input_source */
    uint8_t type; /* ta_msg_event_type */
