_Static_assert(offsetof(ta_msg_tel_trace_wire, transitions) == 256, "tel.trace.transitions");
_Static_assert(offsetof(ta_msg_tel_trace_wire, exited) == 264, "tel.trace.exited");
_Static_assert(offsetof(ta_msg_tel_trace_wire, entered) == 272, "tel.trace.entered");
_Static_assert(offsetof(ta_msg_tel_trace_wire, history) == 280, "tel.trace.history");
_Static_assert(offsetof(ta_msg_tel_trace_wire, states) == 288, "tel.trace.states");

typedef struct ta_msg_tel_trace {
    ta_msg_head head;
    uint64_t macrostep;
    uint64_t trace_id_high;
    uint64_t trace_id_low;
    uint64_t cause_session;
    uint64_t cause_macrostep;
    uint64_t actor;
    uint64_t definition;
    uint32_t microstep;
    uint32_t family;
    uint32_t cause_microstep;
    uint32_t cause_family;
    uint32_t at_state;
    uint32_t at_transition;
    uint32_t at_action;
    uint32_t at_iteration;
    uint32_t state;
    uint32_t expr;
    uint32_t action;
    uint32_t iteration;
    uint32_t dropped;
    uint32_t fault_code;
    uint16_t trace_kind;
    uint8_t position;
    uint8_t result;
    uint8_t event_type;
    uint8_t context_flags;
    uint8_t context_detail;
    ta_bytes event_name;
    ta_bytes event_send_id;
    ta_bytes event_invoke_id;
    ta_bytes event_data;
    ta_bytes name;
    ta_bytes send;
    ta_bytes invoke;
    ta_bytes value;
    ta_bytes fault_detail;
    ta_bytes fault_message;
    ta_bytes fault_data;
    ta_bytes identity_family;
    ta_bytes identity_revision;
    ta_bytes transitions;
    ta_bytes exited;
    ta_bytes entered;
    ta_bytes history;
    ta_bytes states;
} ta_msg_tel_trace;

/*
 * ta_msg_tel_trace_size sets *size to the exact size in bytes of the tel.trace
 * record that ta_msg_tel_trace_write stores for data: 296 fixed bytes and the
 * bytes of its 18 spans (event_name, event_send_id, event_invoke_id,
 * event_data, name, send, invoke, value, fault_detail, fault_message,
 * fault_data, identity_family, identity_revision, transitions, exited,
 * entered, history, states), rounded up to a multiple of 8. It never
 * allocates. TA_ERR_NOMEM: the total does not fit a u32 (or size_t), and *size
 * is untouched. TA_ERR_INVALID: a ta_bytes has a length and no pointer, and
 * *size is untouched. data and size must not be NULL.
 */
ta_result ta_msg_tel_trace_size(const ta_msg_tel_trace *data, uint32_t *size);

/*
 * ta_msg_tel_trace_write fills the reservation `to` with the tel.trace record
 * for data: the header (kind 0x0301, the flags, session and at of data->head,
 * the size, and the seq of the reservation), the fixed fields, the bytes of
 * each span, and zero for every pad and rounding byte, so that all of to->size
 * bytes are stored. It needs a reservation of exactly the size
 * ta_msg_tel_trace_size answers (ring.h: ta_ring_reserve), and the ta_bytes of
 * data must not overlap it. TA_ERR_INVALID, with nothing stored: no bytes, a
 * size other than the measured one, a flag bit that tel.trace does not define,
 * an enum or bool field outside its set (the reader would refuse the record),
 * or a ta_bytes with a length and no pointer. TA_ERR_NOMEM, with nothing
 * stored: the size does not fit a u32. The caller then commits the
 * reservation, or abandons it on an error. It never allocates, and the data
 * may be freed when it returns.
 */
ta_result ta_msg_tel_trace_write(const ta_msg_tel_trace *data, const ta_ring_reservation *to);

/*
 * ta_msg_tel_trace_get decodes the tel.trace record into *out. It needs a
 * record that ta_record_check accepted, so every span is inside it and every
 * enum and bool is in range. The scalars of *out are copies of the record's
 * snapshot (not of the ring bytes, which a host may be rewriting) and may
 * outlive the record. Each ta_bytes of *out points into the record and is
 * valid only until ta_ring_release; its bytes are untrusted, and text is not
 * checked for UTF-8. TA_ERR_INVALID: the record is of another kind, and *out
 * is untouched. It never allocates and reads nothing outside record->fixed and
 * the validated spans.
 */
ta_result ta_msg_tel_trace_get(const ta_record *record, ta_msg_tel_trace *out);

/*
 * tel.dropped: Telemetry records were dropped.
 *
 * Ring tel, kind 0x0302, 48 fixed bytes, 0 spans.
 *
 * Fields:
 *   count (u64): unsigned 64-bit integer
 *   first_seq (seq): the seq the first dropped record would have had
 */
typedef struct ta_msg_tel_dropped_wire {
    ta_msg_wire_header header;
    uint64_t count;
    uint64_t first_seq;
} ta_msg_tel_dropped_wire;
_Static_assert(sizeof(ta_msg_tel_dropped_wire) == 48, "tel.dropped");
_Static_assert(offsetof(ta_msg_tel_dropped_wire, count) == 32, "tel.dropped.count");
_Static_assert(offsetof(ta_msg_tel_dropped_wire, first_seq) == 40, "tel.dropped.first_seq");

typedef struct ta_msg_tel_dropped {
    ta_msg_head head;
    uint64_t count;
    uint64_t first_seq;
} ta_msg_tel_dropped;

/*
 * ta_msg_tel_dropped_size sets *size to the exact size in bytes of the
 * tel.dropped record that ta_msg_tel_dropped_write stores for data: 48 fixed
 * bytes, so always that many. It never allocates. It cannot fail. data and
 * size must not be NULL.
 */
ta_result ta_msg_tel_dropped_size(const ta_msg_tel_dropped *data, uint32_t *size);

/*
 * ta_msg_tel_dropped_write fills the reservation `to` with the tel.dropped
 * record for data: the header (kind 0x0302, the flags, session and at of
 * data->head, the size, and the seq of the reservation), the fixed fields, the
 * bytes of each span, and zero for every pad and rounding byte, so that all of
 * to->size bytes are stored. It needs a reservation of exactly the size
 * ta_msg_tel_dropped_size answers (ring.h: ta_ring_reserve), and the ta_bytes
 * of data must not overlap it. TA_ERR_INVALID, with nothing stored: no bytes,
 * a size other than the measured one, a flag bit that tel.dropped does not
 * define, an enum or bool field outside its set (the reader would refuse the
 * record), or a ta_bytes with a length and no pointer. TA_ERR_NOMEM, with
 * nothing stored: the size does not fit a u32. The caller then commits the
 * reservation, or abandons it on an error. It never allocates, and the data
 * may be freed when it returns.
 */
ta_result ta_msg_tel_dropped_write(const ta_msg_tel_dropped *data, const ta_ring_reservation *to);

/*
 * ta_msg_tel_dropped_get decodes the tel.dropped record into *out. It needs a
 * record that ta_record_check accepted, so every span is inside it and every
 * enum and bool is in range. The scalars of *out are copies of the record's
 * snapshot (not of the ring bytes, which a host may be rewriting) and may
 * outlive the record. Each ta_bytes of *out points into the record and is
 * valid only until ta_ring_release; its bytes are untrusted, and text is not
 * checked for UTF-8. TA_ERR_INVALID: the record is of another kind, and *out
 * is untouched. It never allocates and reads nothing outside record->fixed and
 * the validated spans.
 */
ta_result ta_msg_tel_dropped_get(const ta_record *record, ta_msg_tel_dropped *out);

/*
 * ta_msg_table returns the descriptors of every message in this build, sorted by
 * kind, for ta_record_reader_init. The table is static const data (system
 * lifetime): the pointer stays valid for as long as the library is loaded.
 */
const ta_record_table *ta_msg_table(void);
